public static double bestJump(double[] jumps) {
    double best = jumps[0];
    for (int i = 1; i < jumps.length; i++) {
        if (jumps[i] > best) {
            best = jumps[i];
        }
    }
    return best;
}

public static double bestRun(double[] runs) {
    double best = runs[0];
    for (int i = 1; i < runs.length; i++) {
        if (runs[i] < best) {
            best = runs[i];
        }
    }
    return best;
}

