System.out.println("סעיף א, בדיקה 2 (הטובה ביותר ראשונה): " + check(bestJump(new double[] { 5.2, 4.9, 3.75 }), 5.2));
System.out.println("סעיף א, בדיקה 3 (הטובה ביותר אחרונה): " + check(bestJump(new double[] { 3.25, 3.5, 4.75 }), 4.75));
System.out.println("סעיף א, בדיקה 4 (תלמיד אחד): " + check(bestJump(new double[] { 3.9 }), 3.9));
System.out.println("סעיף ב, בדיקה 1 (הדוגמה): " + check(bestRun(new double[] { 14.2, 13.45, 15.1, 12.85, 13.9 }), 12.85));
System.out.println("סעיף ב, בדיקה 2 (הטובה ביותר ראשונה): " + check(bestRun(new double[] { 11.5, 12.25, 13.75 }), 11.5));
System.out.println("סעיף ב, בדיקה 3 (הטובה ביותר אחרונה): " + check(bestRun(new double[] { 15.5, 14.25, 13.1 }), 13.1));
System.out.println("סעיף ב, בדיקה 4 (תלמיד אחד): " + check(bestRun(new double[] { 14.6 }), 14.6));

